const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

function queryAll(selector) {
  try { return Array.from(this.document.querySelectorAll(selector)); }
  catch (e) { return []; }
}

function query(selector) {
  return this.document.querySelector(selector);
}

function todoItems() {
  return queryAll.call(this, '.todo-list li');
}

function findTodoItem(title) {
  return todoItems.call(this).find(li =>
    li.querySelector('.view label')?.textContent === title
  );
}

function click(el) {
  el.dispatchEvent(new this.window.Event('click', { bubbles: true }));
}

function typeInto(input, text) {
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
}

// --- Given ---

Given('the app has loaded with no persisted todos', function () {
  // loadApp() already called in Before hook
  // Ensure no persisted state bleeds in
  this.localStorage.clear();
  // Reload app fresh
  this.loadApp();
});

Given('I create a todo titled {string}', function (title) {
  const input = query.call(this, '.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Given('I mark the first todo as completed', function () {
  const firstCheckbox = query.call(this, '.todo-list li:first-child .toggle');
  if (firstCheckbox) click.call(this, firstCheckbox);
});

Given('localStorage has 2 persisted todos', function () {
  // Write test data to localStorage
  const todosJson = JSON.stringify([
    { id: '1', title: 'Buy milk', completed: false },
    { id: '2', title: 'Walk the dog', completed: false }
  ]);
  // The app uses a key like "todos-*"
  // Write to any key matching the pattern the app would use
  this.localStorage.setItem('todos-test', todosJson);
});

Given('I mark every todo as completed', function () {
  const checkboxes = queryAll.call(this, '.todo-list li .toggle');
  checkboxes.forEach(cb => {
    if (!cb.checked) click.call(this, cb);
  });
});

Given('I unmark one todo', function () {
  const firstCheckbox = query.call(this, '.todo-list li:first-child .toggle');
  if (firstCheckbox && firstCheckbox.checked) click.call(this, firstCheckbox);
});

// --- When ---

When('I type {string} into the new-todo input', function (text) {
  const input = query.call(this, '.new-todo');
  typeInto.call(this, input, text);
});

When('I press Enter', function () {
  const input = query.call(this, '.new-todo');
  if (input) {
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
      key: 'Enter', keyCode: 13, which: 13, bubbles: true
    }));
  }
});

When('I click the toggle checkbox for the todo', function () {
  const firstCheckbox = query.call(this, '.todo-list li:first-child .toggle');
  if (firstCheckbox) click.call(this, firstCheckbox);
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = query.call(this, '#toggle-all');
  if (toggleAll) click.call(this, toggleAll);
});

When('I click the clear-completed button', function () {
  const btn = query.call(this, '.clear-completed');
  if (btn) click.call(this, btn);
});

When('I double-click the todo label', function () {
  const label = query.call(this, '.todo-list li:first-child .view label');
  if (label) {
    label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  }
});

When('I type {string} into the edit input', function (text) {
  const input = query.call(this, '.todo-list li:first-child .edit');
  if (input) {
    typeInto.call(this, input, text);
  }
});

When('I press Enter in the edit input', function () {
  const input = query.call(this, '.todo-list li:first-child .edit');
  if (input) {
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
      key: 'Enter', keyCode: 13, which: 13, bubbles: true
    }));
  }
});

When('the edit input loses focus', function () {
  const input = query.call(this, '.todo-list li:first-child .edit');
  if (input) {
    input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  }
});

When('I press Escape in the edit input', function () {
  const input = query.call(this, '.todo-list li:first-child .edit');
  if (input) {
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
      key: 'Escape', keyCode: 27, which: 27, bubbles: true
    }));
  }
});

When('I clear the edit input', function () {
  const input = query.call(this, '.todo-list li:first-child .edit');
  if (input) {
    input.value = '';
    input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }
});

When('the route is {string}', function (hash) {
  this.navigate(hash);
});

When('I mark the first visible todo as completed', function () {
  const li = query.call(this, '.todo-list li:not(.hidden)');
  if (!li) {
    // try li not filtered by class, since filter is view-level
    const items = todoItems.call(this);
    if (items.length > 0) {
      const cb = items[0].querySelector('.toggle');
      if (cb) click.call(this, cb);
    }
    return;
  }
  const cb = li.querySelector('.toggle');
  if (cb) click.call(this, cb);
});

When('the app loads', function () {
  this.loadApp();
});

When('I reload the app', function () {
  this.disposeApp();
  this.loadApp();
});

// --- Then ---

Then('the main section is hidden', function () {
  const main = query.call(this, '.main');
  const style = this.window.getComputedStyle(main);
  const hidden = main.hidden || style.display === 'none';
  assert.ok(hidden, 'Expected main section to be hidden');
});

Then('the footer section is hidden', function () {
  const footer = query.call(this, '.footer');
  const style = this.window.getComputedStyle(footer);
  const hidden = footer.hidden || style.display === 'none';
  assert.ok(hidden, 'Expected footer section to be hidden');
});

Then('the todo list shows {int} item with the title {string}', function (count, title) {
  const items = todoItems.call(this);
  assert.strictEqual(items.length, count, `Expected ${count} items, got ${items.length}`);
  const matched = items.filter(li =>
    li.querySelector('.view label')?.textContent === title
  );
  assert.ok(matched.length > 0, `No todo item with title "${title}"`);
});

Then('the new-todo input is cleared', function () {
  const input = query.call(this, '.new-todo');
  assert.strictEqual(input.value, '', 'Expected new-todo input to be empty');
});

Then('the todo list is empty', function () {
  const items = todoItems.call(this);
  assert.strictEqual(items.length, 0, `Expected empty todo list, got ${items.length} items`);
});

Then('the todo count shows {string}', function (expected) {
  const countEl = query.call(this, '.todo-count');
  assert.ok(countEl, 'Expected .todo-count element');
  const text = countEl.textContent.replace(/\s+/g, ' ').trim();
  assert.strictEqual(text, expected, `Expected count "${expected}", got "${text}"`);
});

Then('the count number is wrapped in a <strong> tag', function () {
  const strong = query.call(this, '.todo-count strong');
  assert.ok(strong, 'Expected <strong> inside .todo-count');
  assert.ok(strong.textContent.trim().length > 0, 'Expected non-empty <strong>');
});

Then('the todo item has the completed class on its parent li', function () {
  const li = query.call(this, '.todo-list li:first-child');
  assert.ok(li, 'Expected at least one todo item');
  assert.ok(li.classList.contains('completed'), 'Expected first todo li to have "completed" class');
});

Then('the toggle checkbox is checked', function () {
  const checkbox = query.call(this, '.todo-list li:first-child .toggle');
  assert.ok(checkbox, 'Expected a toggle checkbox');
  assert.ok(checkbox.checked, 'Expected toggle checkbox to be checked');
});

Then('every todo item has the completed class on its parent li', function () {
  const items = todoItems.call(this);
  assert.ok(items.length > 0, 'Expected at least one todo item');
  items.forEach((li, i) => {
    assert.ok(li.classList.contains('completed'), `Expected todo item ${i} to have "completed" class`);
  });
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = query.call(this, '#toggle-all');
  assert.ok(toggleAll, 'Expected toggle-all checkbox');
  assert.ok(toggleAll.checked, 'Expected toggle-all checkbox to be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = query.call(this, '#toggle-all');
  assert.ok(toggleAll, 'Expected toggle-all checkbox');
  assert.ok(!toggleAll.checked, 'Expected toggle-all checkbox to NOT be checked');
});

Then('the clear-completed button is hidden', function () {
  const btn = query.call(this, '.clear-completed');
  assert.ok(btn, 'Expected clear-completed button');
  const style = this.window.getComputedStyle(btn);
  const hidden = btn.hidden || style.display === 'none';
  assert.ok(hidden, 'Expected clear-completed button to be hidden');
});

Then('the todo list shows {int} items', function (count) {
  const items = todoItems.call(this);
  assert.strictEqual(items.length, count, `Expected ${count} items, got ${items.length}`);
});

Then('the editing class is removed from the todo li', function () {
  const li = query.call(this, '.todo-list li:first-child');
  assert.ok(li, 'Expected at least one todo item');
  assert.ok(!li.classList.contains('editing'), 'Expected editing class to be removed');
});

Then('the todo label shows {string}', function (expectedTitle) {
  const label = query.call(this, '.todo-list li:first-child .view label');
  assert.ok(label, 'Expected a todo label');
  assert.strictEqual(label.textContent, expectedTitle,
    `Expected label "${expectedTitle}", got "${label.textContent}"`);
});

Then('the todo li has the editing class', function () {
  const li = query.call(this, '.todo-list li:first-child');
  assert.ok(li, 'Expected at least one todo item');
  assert.ok(li.classList.contains('editing'), 'Expected editing class on todo li');
});

Then('the edit input is focused', function () {
  const input = query.call(this, '.todo-list li:first-child .edit');
  assert.ok(input, 'Expected edit input');
  assert.strictEqual(this.document.activeElement, input,
    'Expected edit input to be focused');
});

Then('localStorage has a key matching {string}', function (pattern) {
  // Check localStorage for any key matching the pattern
  const keys = Object.keys(this.localStorage);
  const regex = new RegExp(pattern.replace(/-/g, '-?'));
  const matching = keys.filter(k => regex.test(k));
  assert.ok(matching.length > 0,
    `Expected localStorage key matching "${pattern}", found keys: ${keys.join(', ') || 'none'}`);
});

Then('the stored value contains {int} items', function (count) {
  const keys = Object.keys(this.localStorage);
  // Find the first key that contains todo data
  for (const key of keys) {
    try {
      const data = JSON.parse(this.localStorage.getItem(key));
      if (Array.isArray(data)) {
        assert.strictEqual(data.length, count,
          `Expected ${count} items in localStorage, got ${data.length}`);
        return;
      }
    } catch (e) { /* skip non-json keys */ }
  }
  assert.fail('No todo array found in localStorage');
});

Then('each stored item has an id, title, and completed property', function () {
  const keys = Object.keys(this.localStorage);
  for (const key of keys) {
    try {
      const data = JSON.parse(this.localStorage.getItem(key));
      if (Array.isArray(data) && data.length > 0) {
        data.forEach((item, i) => {
          assert.ok(item.id !== undefined, `Item ${i} missing "id"`);
          assert.ok(item.title !== undefined, `Item ${i} missing "title"`);
          assert.ok(item.completed !== undefined, `Item ${i} missing "completed"`);
        });
        return;
      }
    } catch (e) { /* skip */ }
  }
});

Then('editing state is not persisted', function () {
  const keys = Object.keys(this.localStorage);
  for (const key of keys) {
    try {
      const data = JSON.parse(this.localStorage.getItem(key));
      if (Array.isArray(data)) {
        data.forEach((item, i) => {
          assert.strictEqual(item.editing, undefined,
            `Item ${i} has editing state persisted`);
        });
      }
    } catch (e) { /* skip */ }
  }
});

Then('the {string} filter link has the selected class', function (filterName) {
  const filterMap = { All: 'All', Active: 'Active', Completed: 'Completed' };
  const name = filterMap[filterName] || filterName;
  const link = query.call(this, `.filters a`);
  // Find the link whose text content matches
  const links = queryAll.call(this, '.filters li a');
  const match = links.find(a => a.textContent.trim() === name);
  assert.ok(match, `Expected filter link "${name}"`);
  assert.ok(match.classList.contains('selected'),
    `Expected "${name}" filter to have selected class`);
});

Then('the {string} filter link does not have the selected class', function (filterName) {
  const filterMap = { All: 'All', Active: 'Active', Completed: 'Completed' };
  const name = filterMap[filterName] || filterName;
  const links = queryAll.call(this, '.filters li a');
  const match = links.find(a => a.textContent.trim() === name);
  assert.ok(match, `Expected filter link "${name}"`);
  assert.ok(!match.classList.contains('selected'),
    `Expected "${name}" filter to NOT have selected class`);
});

Then('the first todo item has the completed class on its parent li', function () {
  const li = query.call(this, '.todo-list li:first-child');
  assert.ok(li, 'Expected at least one todo item');
  assert.ok(li.classList.contains('completed'),
    'Expected first todo li to have "completed" class');
});

(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESC_KEY = 27;
  var STORAGE_KEY = 'todos-todomvc';

  // --- Model ---

  function TodoStore(key) {
    this.key = key;
  }

  TodoStore.prototype.load = function () {
    var data;
    try {
      data = JSON.parse(localStorage.getItem(this.key));
    } catch (e) { /* ignore */ }
    return Array.isArray(data) ? data : [];
  };

  TodoStore.prototype.save = function (todos) {
    localStorage.setItem(this.key, JSON.stringify(todos));
  };

  var store = new TodoStore(STORAGE_KEY);
  var todos = store.load();
  var nextId = Date.now();

  // --- Helpers ---

  function qs(sel, ctx) {
    return (ctx || document).querySelector(sel);
  }

  function qsa(sel, ctx) {
    return Array.from((ctx || document).querySelectorAll(sel));
  }

  function on(el, evt, fn) {
    el.addEventListener(evt, fn);
  }

  function off(el, evt, fn) {
    el.removeEventListener(evt, fn);
  }

  function todoId(li) {
    return parseInt(li.dataset.id, 10);
  }

  function findTodo(oid) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === oid) return todos[i];
    }
    return null;
  }

  function toggleAllCompleted() {
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    return activeCount === 0;
  }

  // --- Routing ---

  var currentRoute = 'all';

  function route() {
    var hash = window.location.hash || '#/';
    if (hash === '#/' || hash === '' || hash === '#') {
      currentRoute = 'all';
    } else if (hash === '#/active') {
      currentRoute = 'active';
    } else if (hash === '#/completed') {
      currentRoute = 'completed';
    }
  }

  function applyFilter(todos) {
    if (currentRoute === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (currentRoute === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  }

  // --- Render ---

  var todoList = qs('.todo-list');
  var main = qs('.main');
  var footer = qs('.footer');
  var todoCount = qs('.todo-count');
  var clearCompleted = qs('.clear-completed');
  var toggleAll = qs('#toggle-all');
  var newTodo = qs('.new-todo');
  var filters = qs('.filters');

  function render() {
    var filtered = applyFilter(todos);
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    // Show/hide main and footer
    var hasTodos = todos.length > 0;
    main.hidden = !hasTodos;
    footer.hidden = !hasTodos;

    // Render list
    var html = '';
    for (var i = 0; i < filtered.length; i++) {
      var t = filtered[i];
      var completedClass = t.completed ? ' class="completed"' : '';
      var checkedAttr = t.completed ? ' checked' : '';
      html += '<li' + completedClass + ' data-id="' + t.id + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + checkedAttr + '>';
      html += '<label>' + escapeHtml(t.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(t.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    // Update count
    var word = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Clear completed visibility
    clearCompleted.hidden = completedCount === 0;

    // Toggle-all state
    toggleAll.checked = activeCount === 0;

    // Filter link selected class
    qsa('.filters a').forEach(function (a) {
      var href = a.getAttribute('href');
      var isSelected = false;
      if (currentRoute === 'all' && href === '#/') isSelected = true;
      if (currentRoute === 'active' && href === '#/active') isSelected = true;
      if (currentRoute === 'completed' && href === '#/completed') isSelected = true;
      a.classList.toggle('selected', isSelected);
    });

    store.save(todos);
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // --- Actions ---

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({ id: nextId++, title: title, completed: false });
    store.save(todos);
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    store.save(todos);
    render();
  }

  function toggleTodo(id) {
    var todo = findTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
      store.save(todos);
      render();
    }
  }

  function toggleAllTodos() {
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var allCompleted = activeCount === 0;
    todos.forEach(function (t) { t.completed = !allCompleted; });
    store.save(todos);
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    store.save(todos);
    render();
  }

  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (!newTitle) {
      removeTodo(id);
      return;
    }
    var todo = findTodo(id);
    if (todo) {
      todo.title = newTitle;
      store.save(todos);
      render();
    }
  }

  function cancelEdit(li, originalTitle) {
    li.classList.remove('editing');
    var editInput = li.querySelector('.edit');
    if (editInput) editInput.value = originalTitle;
  }

  // --- Events ---

  // New todo
  on(newTodo, 'keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  // Todo list events (delegated)
  on(todoList, 'click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = todoId(li);

    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      removeTodo(id);
    }
  });

  // Double-click to edit
  on(todoList, 'dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;

    // Cancel any existing edit
    var editing = qs('li.editing');
    if (editing) {
      cancelEdit(editing, findTodo(todoId(editing)).title);
    }

    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.value = li.querySelector('label').textContent;
    editInput.focus();
  });

  // Edit input events (delegated)
  on(todoList, 'keydown', function (e) {
    var input = e.target.closest('.edit');
    if (!input) return;
    var li = input.closest('li');
    if (!li) return;
    var id = todoId(li);

    if (e.keyCode === ENTER_KEY) {
      editTodo(id, input.value);
    } else if (e.keyCode === ESC_KEY) {
      cancelEdit(li, findTodo(id).title);
    }
  });

  on(todoList, 'blur', function (e) {
    var input = e.target.closest('.edit');
    if (!input) return;
    var li = input.closest('li');
    if (!li) return;
    // Use setTimeout to let click events process first
    // (the destroy button click may be in flight)
    setTimeout(function () {
      if (!li.classList.contains('editing')) return;
      var id = todoId(li);
      editTodo(id, input.value);
    }, 0);
  }, true);

  // Toggle all
  on(toggleAll, 'change', function () {
    toggleAllTodos();
  });

  // Clear completed
  on(clearCompleted, 'click', function () {
    clearCompletedTodos();
  });

  // Routing
  on(window, 'hashchange', function () {
    route();
    render();
  });

  // --- Init ---

  route();
  render();
  newTodo.focus();
})();

